use super::*;

pub(crate) fn stats_json(s: &Stats) -> serde_json::Value {
    serde_json::json!({
        "n": s.n,
        "median": s.median,
        "mean": (s.mean * 10.0).round() / 10.0,
        "p90": s.p90,
        "max": s.max,
        "overFramePct": s.over_frame_pct.round(),
    })
}
